```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name, c.span_name, count(*) n, approx_quantile(CAST(epoch_ms(s.time)-epoch_ms(c.time) AS DOUBLE),0.5) gap_ms_p50, approx_quantile(c.duration,0.5)/1e6 cli_p50_ms, approx_quantile(s.duration,0.95)/1e6 srv_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name='search' AND c.span_name='rate.Rate/GetRates' GROUP BY 1,2", "claim": "search→rate GetRates client spans take ~2s; the rate server span starts ~1.6s later, yet rate's own server time is under 1ms."},
        {"kind": "trace", "sql": "SELECT c.service_name, c.span_name, count(*) n, approx_quantile(c.duration,0.95)/1e6 cli_p95_ms, approx_quantile(CAST(epoch_ms(s.time)-epoch_ms(c.time) AS DOUBLE),0.5) gap_ms_p50 FROM normal_traces c JOIN normal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name='search' AND c.span_name IN ('rate.Rate/GetRates','geo.Geo/Nearby') GROUP BY 1,2", "claim": "Normal period: search→rate and search→geo client spans have near-zero start gap and sub-6ms p95 latency."},
        {"kind": "trace", "sql": "SELECT c.span_name, count(*) n, approx_quantile(c.duration,0.95)/1e6 cli_p95_ms, approx_quantile(CAST(epoch_ms(s.time)-epoch_ms(c.time) AS DOUBLE),0.5) gap_ms_p50 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name='search' AND c.span_name IN ('rate.Rate/GetRates','geo.Geo/Nearby') GROUP BY 1", "claim": "In the incident, search→geo stays fast (~0.66ms p95) while search→rate is slow (~2.6s p95), so only that connection is affected."}
      ]
    }
  ],
  "propagation": [
    {"from": "rate", "to": "search",
     "evidence": [{"kind": "trace", "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 cli_p95_ms, approx_quantile(s.duration,0.95)/1e6 srv_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.span_name='rate.Rate/GetRates' GROUP BY 1,2", "claim": "The rate.GetRates call from search is slow at the client (~2.6s p95) while rate's server span stays under 1ms."}]},
    {"from": "search", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE 'HTTP%' GROUP BY 1", "claim": "frontend HTTP /hotels p95 rises to ~2.6s (from ~12ms) while other HTTP paths stay flat; /hotels is the search-dependent path."}]}
  ]
}
